-- =============================================================================
-- Venture reporting — Phase 1 (ADDITIVE ONLY)
-- Static profile (versioned), founders, team snapshot, baseline, stage
-- settings, money bands and glossary. Nothing here touches an existing table.
--
-- Contract of scripts/db-audit/apply-schema-file.mjs: one statement per line,
-- each terminated by ';', no ';' inside string literals.
-- =============================================================================

CREATE TABLE IF NOT EXISTS venture_stage_settings (id SERIAL PRIMARY KEY, setting_key TEXT NOT NULL, business_model TEXT NOT NULL DEFAULT 'default', setting_value NUMERIC NOT NULL, value_type TEXT NOT NULL DEFAULT 'number', effective_from DATE NOT NULL DEFAULT CURRENT_DATE, updated_by TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE (setting_key, business_model, effective_from));
CREATE INDEX IF NOT EXISTS idx_vss_key ON venture_stage_settings (setting_key, business_model, effective_from DESC);
CREATE TABLE IF NOT EXISTS venture_band_settings (id SERIAL PRIMARY KEY, band_kind TEXT NOT NULL CHECK (band_kind IN ('flow','cash')), band_code TEXT NOT NULL, sort_order INTEGER NOT NULL, low NUMERIC, high NUMERIC, midpoint NUMERIC, effective_from DATE NOT NULL DEFAULT CURRENT_DATE, UNIQUE (band_kind, band_code, effective_from));
CREATE INDEX IF NOT EXISTS idx_vbs_kind ON venture_band_settings (band_kind, sort_order);
CREATE TABLE IF NOT EXISTS venture_static_profile (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), venture_uuid UUID NOT NULL REFERENCES ventures(id) ON DELETE CASCADE, venture_code TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, effective_from DATE NOT NULL, is_current BOOLEAN NOT NULL DEFAULT TRUE, legal_name TEXT, trade_name TEXT, founding_date DATE, registration_status TEXT, registration_country TEXT, pays_taxes BOOLEAN, social_protection BOOLEAN, sector TEXT, business_model TEXT, problem_statement TEXT, ideal_customer_profile TEXT, countries_of_operation TEXT[], north_star_name TEXT, north_star_definition TEXT, north_star_unit TEXT, reporting_currency TEXT NOT NULL DEFAULT 'XOF', accounting_basis TEXT CHECK (accounting_basis IN ('cash','accrual')), vat_included BOOLEAN, created_by TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), superseded_at TIMESTAMPTZ, superseded_by TEXT, superseded_reason TEXT, UNIQUE (venture_uuid, version));
CREATE UNIQUE INDEX IF NOT EXISTS idx_vsp_current ON venture_static_profile (venture_uuid) WHERE is_current;
CREATE TABLE IF NOT EXISTS venture_founder (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), venture_uuid UUID NOT NULL REFERENCES ventures(id) ON DELETE CASCADE, venture_code TEXT NOT NULL, contact_id TEXT REFERENCES contacts(cid) ON DELETE SET NULL, name TEXT NOT NULL, gender TEXT CHECK (gender IN ('female','male','other','undisclosed')), date_of_birth DATE, role TEXT, employment_type TEXT CHECK (employment_type IN ('full_time','part_time')), is_current BOOLEAN NOT NULL DEFAULT TRUE, effective_from DATE NOT NULL DEFAULT CURRENT_DATE, created_by TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_vf_venture ON venture_founder (venture_uuid) WHERE is_current;
CREATE TABLE IF NOT EXISTS venture_team_snapshot (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), venture_uuid UUID NOT NULL REFERENCES ventures(id) ON DELETE CASCADE, venture_code TEXT NOT NULL, reporting_period DATE NOT NULL, women_employees INTEGER NOT NULL DEFAULT 0, men_employees INTEGER NOT NULL DEFAULT 0, under35_women INTEGER NOT NULL DEFAULT 0, under35_men INTEGER NOT NULL DEFAULT 0, full_time_employees INTEGER NOT NULL DEFAULT 0, part_time_employees INTEGER NOT NULL DEFAULT 0, part_time_days NUMERIC NOT NULL DEFAULT 0, full_time_founders INTEGER NOT NULL DEFAULT 0, part_time_founders INTEGER NOT NULL DEFAULT 0, created_by TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE (venture_uuid, reporting_period));
CREATE TABLE IF NOT EXISTS venture_baseline (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), venture_uuid UUID NOT NULL REFERENCES ventures(id) ON DELETE CASCADE, venture_code TEXT NOT NULL, captured_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), fte NUMERIC, paying_customers INTEGER, cash_mode TEXT CHECK (cash_mode IN ('exact','band')), cash_value NUMERIC, cash_band TEXT, outside_financing_mode TEXT CHECK (outside_financing_mode IN ('exact','band')), outside_financing_value NUMERIC, outside_financing_band TEXT, is_locked BOOLEAN NOT NULL DEFAULT TRUE, superseded_at TIMESTAMPTZ, superseded_by TEXT, superseded_reason TEXT, created_by TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS idx_vb_active ON venture_baseline (venture_uuid) WHERE superseded_at IS NULL;
CREATE TABLE IF NOT EXISTS venture_glossary (id SERIAL PRIMARY KEY, term TEXT NOT NULL UNIQUE, definition_en TEXT NOT NULL, definition_fr TEXT NOT NULL, updated_by TEXT, updated_at TIMESTAMPTZ DEFAULT NOW());
INSERT INTO venture_stage_settings (setting_key, business_model, setting_value, value_type, effective_from) VALUES ('consecutive_months_required','default',3,'months','2026-11-01'), ('min_customer_growth_monthly','default',5,'percent','2026-11-01'), ('min_monthly_retention_early_traction','default',50,'percent','2026-11-01'), ('min_monthly_retention_growth','default',50,'percent','2026-11-01'), ('min_ltv_cac','default',3,'number','2026-11-01'), ('validation_min_interviews','default',10,'count','2026-11-01'), ('early_traction_min_paying_customers','default',5,'count','2026-11-01'), ('growth_min_paying_customers','default',15,'count','2026-11-01'), ('scaling_sustained_growth_months','default',6,'months','2026-11-01'), ('scaling_min_monthly_retention','default',70,'percent','2026-11-01'), ('scaling_min_non_founder_fte','default',5,'count','2026-11-01'), ('review_flag_months','default',3,'months','2026-11-01') ON CONFLICT (setting_key, business_model, effective_from) DO NOTHING;
INSERT INTO venture_band_settings (band_kind, band_code, sort_order, low, high, midpoint, effective_from) VALUES ('flow','F0',0,0,0,0,'2026-11-01'), ('flow','F1',1,1,50000,25000.5,'2026-11-01'), ('flow','F2',2,50001,100000,75000.5,'2026-11-01'), ('flow','F3',3,100001,250000,175000.5,'2026-11-01'), ('flow','F4',4,250001,500000,375000.5,'2026-11-01'), ('flow','F5',5,500001,1000000,750000.5,'2026-11-01'), ('flow','F6',6,1000001,2500000,1750000.5,'2026-11-01'), ('flow','F7',7,2500001,5000000,3750000.5,'2026-11-01'), ('flow','F8',8,5000001,6250001.25,5625001.125,'2026-11-01'), ('cash','C0',0,0,0,0,'2026-11-01'), ('cash','C1',1,1,500000,250000.5,'2026-11-01'), ('cash','C2',2,500001,1000000,750000.5,'2026-11-01'), ('cash','C3',3,1000001,2500000,1750000.5,'2026-11-01'), ('cash','C4',4,2500001,5000000,3750000.5,'2026-11-01'), ('cash','C5',5,5000001,10000000,7500000.5,'2026-11-01'), ('cash','C6',6,10000001,25000000,17500000.5,'2026-11-01'), ('cash','C7',7,25000001,31250001.25,28125001.125,'2026-11-01') ON CONFLICT (band_kind, band_code, effective_from) DO NOTHING;
INSERT INTO venture_glossary (term, definition_en, definition_fr) VALUES ('mrr','Monthly recurring revenue from subscriptions, excluding one-off income.','Revenu récurrent mensuel des abonnements, hors revenus ponctuels.'), ('paying_customer','A customer who paid at least once in the reporting month.','Un client ayant payé au moins une fois pendant le mois de référence.'), ('active_user','A person who used the product at least once during the reporting month.','Une personne ayant utilisé le produit au moins une fois pendant le mois de référence.'), ('fte','Full-time employees + (part-time days worked ÷ 20) + full-time founders.','Employés à temps plein + (jours travaillés à temps partiel ÷ 20) + fondateurs à temps plein.') ON CONFLICT (term) DO NOTHING;
